\begin{equation}
\mathcal{L}_{\text{enc}} = -\frac{1}{B}\sum_{i=1}^{B}
\log
\frac{\exp(\operatorname{sim}(q_i, s_i^+) / \tau)}
{\sum_{j} \exp(\operatorname{sim}(q_i, s_j) / \tau)}
\end{equation}

\begin{equation}
\mathcal{L}_{\text{LW}} = -\log
\frac{\exp(f(q, s^+) / \tau)}
{\sum_{j=1}^{K} \exp(f(q, s_j) / \tau)}
\end{equation}

\begin{equation}
\mathcal{L}_{\text{PW}} =
-\frac{1}{K}\sum_{j=1}^{K}
\left[
y_j \log \sigma(f_j) + (1-y_j)\log(1-\sigma(f_j))
\right].
\end{equation}
